import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

# Inline CUDA/C++ code implementing a custom linear (matmul + bias), dropout, mean over dim=1, and softmax over dim=1
cuda_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <curand_kernel.h>

// ----------------------------------------------------------------------------
// Custom Linear Forward (x * w^T + b)
// x:  (B, inF)
// w:  (outF, inF)
// b:  (outF)
// out: (B, outF)
// ----------------------------------------------------------------------------
__global__ void custom_linear_forward_kernel(
    const float* __restrict__ x,
    const float* __restrict__ w,
    const float* __restrict__ b,
    float* __restrict__ out,
    int B,
    int inF,
    int outF
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B * outF) {
        int row = idx / outF;  // batch index
        int col = idx % outF;  // output feature index
        float val = b[col];
        for(int i = 0; i < inF; i++){
            val += x[row * inF + i] * w[col * inF + i];
        }
        out[idx] = val;
    }
}

torch::Tensor custom_linear_forward_cuda(torch::Tensor x, torch::Tensor w, torch::Tensor b) {
    int B = x.size(0);
    int inF = x.size(1);
    int outF = w.size(0);

    auto out = torch::zeros({B, outF}, x.options());

    int total = B * outF;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    custom_linear_forward_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        B, inF, outF
    );
    return out;
}

// ----------------------------------------------------------------------------
// Custom Dropout
// p: dropout probability
// out = (in / (1 - p)) if random_val >= p, else 0
// ----------------------------------------------------------------------------
__global__ void custom_dropout_kernel(
    const float* __restrict__ in,
    float* __restrict__ out,
    float p,
    int size,
    unsigned long long seed
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        curandState state;
        curand_init(seed, idx, 0, &state);
        float r = curand_uniform(&state);
        if (r < p) {
            out[idx] = 0.0f;
        } else {
            out[idx] = in[idx] / (1.0f - p);
        }
    }
}

torch::Tensor custom_dropout_cuda(torch::Tensor x, float p) {
    auto out = torch::empty_like(x);
    int size = x.numel();
    int blockSize = 256;
    int gridSize = (size + blockSize - 1) / blockSize;

    // fixed seed for demonstration
    unsigned long long seed = 1234ULL;

    custom_dropout_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        p,
        size,
        seed
    );
    return out;
}

// ----------------------------------------------------------------------------
// Custom Mean over dim=1, keepdim=True
// x: (B, outF) -> out: (B, 1)
// ----------------------------------------------------------------------------
__global__ void custom_mean_dim1_kernel(
    const float* __restrict__ in,
    float* __restrict__ out,
    int B,
    int outF
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B) {
        float sum = 0.0f;
        for(int j = 0; j < outF; j++){
            sum += in[idx * outF + j];
        }
        out[idx] = sum / (float)outF;
    }
}

torch::Tensor custom_mean_dim1_cuda(torch::Tensor x) {
    int B = x.size(0);
    int outF = x.size(1);
    auto out = torch::empty({B, 1}, x.options());

    int blockSize = 256;
    int gridSize = (B + blockSize - 1) / blockSize;

    custom_mean_dim1_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B, outF
    );
    return out;
}

// ----------------------------------------------------------------------------
// Custom Softmax over dim=1
// x: (B, outF)
// ----------------------------------------------------------------------------
__global__ void custom_softmax_dim1_kernel(
    const float* __restrict__ in,
    float* __restrict__ out,
    int B,
    int outF
) {
    int row = blockIdx.x;
    if (row < B) {
        // Find max
        float max_val = in[row * outF];
        for(int j = 1; j < outF; j++){
            float v = in[row * outF + j];
            if (v > max_val) max_val = v;
        }
        // Compute sum of exp
        float sum_exp = 0.0f;
        for(int j = 0; j < outF; j++){
            sum_exp += expf(in[row * outF + j] - max_val);
        }
        // Fill output
        for(int j = 0; j < outF; j++){
            out[row * outF + j] = expf(in[row * outF + j] - max_val) / sum_exp;
        }
    }
}

torch::Tensor custom_softmax_dim1_cuda(torch::Tensor x) {
    int B = x.size(0);
    int outF = x.size(1);
    auto out = torch::empty_like(x);

    dim3 grid(B);
    dim3 block(1);

    custom_softmax_dim1_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B, outF
    );
    return out;
}
