class ModelNew(nn.Module):
    """
    A model that performs a custom linear operation, applies custom dropout,
    calculates the mean over dim=1, and then applies a custom softmax.
    """
    def __init__(self, in_features, out_features, dropout_p):
        super(ModelNew, self).__init__()
        # Store params as parameters for autograd
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))
        self.dropout_p = dropout_p

    def forward(self, x):
        x = custom_ops.custom_linear_forward_cuda(x, self.weight, self.bias)
        x = custom_ops.custom_dropout_cuda(x, self.dropout_p)
        x = custom_ops.custom_mean_dim1_cuda(x)
        x = custom_ops.custom_softmax_dim1_cuda(x)
        return x

